10	/**
11	 * Validates the owner's optional postcode. When present it must be 4 digits and, for a city with a
12	 * known region ({@link Locality}), fall within that region's range (NSW 2000-2099, VIC 3000-3099,
13	 * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An absent postcode is
14	 * left untouched, so the create contract stays backward-compatible. An invalid postcode is a 400
15	 * via {@link MissingOwnerFieldsException}.
16	 */
17	public class ValidateOwnerPostcode {
18	
19	    private static final Map<String, int[]> REGION_RANGE = Map.of(
20	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
21	
22	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
23	        String postcode = owner.getPostcode();
24	        if (postcode == null) {
25	            return;
26	        }
27	        int[] range = REGION_RANGE.get(Locality.of(owner));
28	        if (!postcode.matches("[0-9]{4}")
29	                || (range != null && (Integer.parseInt(postcode) < range[0] || Integer.parseInt(postcode) > range[1]))) {
30	            throw new MissingOwnerFieldsException(List.of("postcode"));
31	        }
32	    }
33	}
