3	import java.util.List;
4	import java.util.Locale;
5	import java.util.Map;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
10	
11	/**
12	 * Rewrites the built owner's address into a canonical form in place, so later steps save, compare
13	 * (household duplicate detection and the shared household id) and return it as {@code address}. The
14	 * value is trimmed, its internal whitespace collapsed, upper-cased and common street-type
15	 * abbreviations expanded (ST->STREET, RD->ROAD, AVE->AVENUE). An address that is blank after
16	 * normalization is rejected 400 via {@link MissingOwnerFieldsException}.
17	 */
18	public class NormalizeOwnerAddress {
19	
20	    private static final Map<String, String> ABBREVIATIONS = Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
21	
22	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
23	        String address = owner.getAddress() == null ? "" : owner.getAddress().trim();
24	        if (address.isEmpty()) {
25	            throw new MissingOwnerFieldsException(List.of("address"));
26	        }
27	        StringBuilder normalized = new StringBuilder();
28	        for (String token : address.split("\\s+")) {
29	            String upper = token.toUpperCase(Locale.ROOT);
30	            if (normalized.length() > 0) {
31	                normalized.append(' ');
32	            }
33	            normalized.append(ABBREVIATIONS.getOrDefault(upper, upper));
34	        }
35	        owner.setAddress(normalized.toString());
36	    }
37	}
