3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
7	
8	/**
9	 * Rejects 409 when the built owner shares another owner's {@link IdentityKey}. This one check
10	 * replaces the former separate telephone, email and household duplicate checks: an owner collides
11	 * only on an exact match of the telephone-and-email identity, so two members of one household with
12	 * different telephones (or different emails) are both allowed.
13	 */
14	public class RejectDuplicateOwnerIdentity {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
17	            throws DuplicateOwnerIdentityException {
18	        String telephone = IdentityKey.telephone(owner);
19	        String email = IdentityKey.email(owner);
20	        for (Owner other : ownerRepository.findAll()) {
21	            if (other != owner && telephone.equals(IdentityKey.telephone(other))
22	                    && email.equals(IdentityKey.email(other))) {
23	                throw new DuplicateOwnerIdentityException(IdentityKey.of(owner));
24	            }
25	        }
26	    }
27	}
