7	
8	/**
9	 * Rejects 409 when the built owner's city already contains 50 or more owners, compared
10	 * case-insensitively after trimming. The new owner is not yet saved, so a city holding
11	 * exactly 50 existing owners rejects the 51st.
12	 */
13	public class RejectOwnerCityAtCapacity {
14	
15	    private static final int CAPACITY = 50;
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws CityAtCapacityException {
18	        String city = normalize(owner.getCity());
19	        int count = 0;
20	        for (Owner other : ownerRepository.findAll()) {
21	            if (other != owner && city.equals(normalize(other.getCity())) && ++count >= CAPACITY) {
22	                throw new CityAtCapacityException(owner.getCity());
23	            }
24	        }
25	    }
26	
27	    private static String normalize(String value) {
28	        return value == null ? "" : value.trim().toLowerCase();
29	    }
30	}
