3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/** Rolls a weekend date forward to the following Monday; business days are returned unchanged. */
7	final class BusinessDay {
8	
9	    private BusinessDay() {
10	    }
11	
12	    static LocalDate nextBusinessDay(LocalDate date) {
13	        DayOfWeek day = date.getDayOfWeek();
14	        if (day == DayOfWeek.SATURDAY) {
15	            return date.plusDays(2);
16	        }
17	        if (day == DayOfWeek.SUNDAY) {
18	            return date.plusDays(1);
19	        }
20	        return date;
21	    }
22	}
