3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's locality from the pinned city-to-region table
9	 * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), or {@code UNKNOWN}
10	 * for any other city.
11	 */
12	public final class Locality {
13	
14	    private static final Map<String, String> CITY_REGION = Map.of(
15	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
16	
17	    private Locality() {
18	    }
19	
20	    public static String of(Owner owner) {
21	        String byPostcode = fromPostcode(owner.getPostcode());
22	        if (byPostcode != null) {
23	            return byPostcode;
24	        }
25	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
26	    }
27	
28	    private static String fromPostcode(String postcode) {
29	        if (postcode == null || !postcode.matches("\\d{4}")) {
30	            return null;
31	        }
32	        int code = Integer.parseInt(postcode);
33	        if (code >= 2000 && code <= 2099) {
34	            return "NSW";
35	        }
36	        if (code >= 3000 && code <= 3099) {
37	            return "VIC";
38	        }
39	        if (code >= 4000 && code <= 4099) {
40	            return "QLD";
41	        }
42	        return null;
43	    }
44	}
