3	import java.util.Objects;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Counts an owner's namesakes: the other owners sharing this owner's first and last name, compared
10	 * case-insensitively. The owner itself is excluded by id, so for a freshly created owner this equals
11	 * the number of owners that existed before the create (none of that owner's namesakes are created by
12	 * the same request), matching the {@code namesakeCount} the create endpoint reports.
13	 */
14	public final class NamesakeCount {
15	
16	    private NamesakeCount() {
17	    }
18	
19	    public static int of(Owner owner, OwnerRepository repository) {
20	        int count = 0;
21	        for (Owner other : repository.findAll()) {
22	            if (!Objects.equals(other.getId(), owner.getId())
23	                    && equalsIgnoreCase(owner.getFirstName(), other.getFirstName())
24	                    && equalsIgnoreCase(owner.getLastName(), other.getLastName())) {
25	                count++;
26	            }
27	        }
28	        return count;
29	    }
30	
31	    private static boolean equalsIgnoreCase(String a, String b) {
32	        return a == null ? b == null : a.equalsIgnoreCase(b);
33	    }
34	}
