3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's numeric membership level from 1 to 3: starts at 1, adds 1 when an email is
7	 * present, adds 1 when {@code namesakeCount} is 0, and is capped at 3 (level 4 is reserved for
8	 * tenure).
9	 */
10	public final class MembershipLevel {
11	
12	    private MembershipLevel() {
13	    }
14	
15	    public static int of(Owner owner, int namesakeCount) {
16	        int level = 1;
17	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
18	            level++;
19	        }
20	        if (namesakeCount == 0) {
21	            level++;
22	        }
23	        return Math.min(level, 3);
24	    }
25	}
