9	/**
10	 * Flags a bulk signup: {@code true} when more than 80 other owners already share this owner's
11	 * {@code registrationDate} (i.e. were created on the same day), otherwise {@code false}. The owner
12	 * itself is excluded by id, matching the daily accumulation the create endpoint reports.
13	 */
14	public final class BulkSignupWarning {
15	
16	    private static final int THRESHOLD = 80;
17	
18	    private BulkSignupWarning() {
19	    }
20	
21	    public static boolean of(Owner owner, OwnerRepository repository) {
22	        LocalDate day = owner.getRegistrationDate();
23	        int count = 0;
24	        for (Owner other : repository.findAll()) {
25	            if (!Objects.equals(other.getId(), owner.getId()) && day.equals(other.getRegistrationDate())
26	                    && ++count > THRESHOLD) {
27	                return true;
28	            }
29	        }
30	        return false;
31	    }
32	}
